    if not isinstance(query, str) or (limit is not None and (type(limit) is not int or not 1 <= limit <= 200)):
        raise DesktopPreparationError("preparation_limit_invalid", "备课任务检索参数不正确。")
    values, invalid = [], 0
    needle = query.strip().casefold()
